draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sweet potato
  ctx.fillStyle = '#FFA07A';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // orange
  ctx.fillStyle = '#FF9900';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.sin(t), H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // vitamin A text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Vitamin A', W/2, H/2 + 70);

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2 + 10);
  ctx.stroke();

  ctx.restore();
}
